const source = $('Execute Workflow Trigger').item.json || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const raw = String(source.rawText || message.text || payload.text || '').trim();
const binaryPropertyName = source.binaryPropertyName || payload.binaryPropertyName || 'data';
const binary = source.binary || payload.binary || {};
const binaryInfo = binary[binaryPropertyName] || {};
const fileName = source.fileName || payload.fileName || binaryInfo.fileName || 'upload.bin';
const folderId = source.folderId || payload.folderId || 'root';
const hasBinary = Boolean(binary[binaryPropertyName]);
return [{ json: { ...source, payload, message, chatId, raw, binaryPropertyName, fileName, folderId, hasTarget: hasBinary, response: hasBinary ? '' : 'Ban hay gui kem file roi nhap: upload file nay vao drive' }, binary }];

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;');
const pickFirst = (...values) => {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  }
  return '';
};
const formatDate = (value) => {
  if (!value) return '';
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? '' : date.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
};

const source = $('Prepare Action').item.json;
const item = $input.item.json || {};
let text = '✅ <b>Da upload file len Google Drive</b>

';
text += '<b>' + escapeHtml(item.name || source.fileName) + '</b>
';
text += 'ID: ' + escapeHtml(item.id || '') + '
';
if (item.webViewLink) text += '🔗 <a href="' + escapeHtml(item.webViewLink) + '">Mo file</a>';
return [{ json: { chatId: source.chatId, text: text.trim() } }];
